    ${custom ? `<label class="custom-entry-label" for="${id}-custom"><span>自由填写</span></label><input class="control custom-entry" id="${id}-custom" data-path="${escapeHtml(path)}" value="${escapeHtml(selected)}" placeholder="输入自己的答案">` : ''}
